import{_ as a,o as r,c as e,a2 as i}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Декларация Симбиотической Цивилизации Якоря","description":"","frontmatter":{},"headers":[],"relativePath":"ru/01-锚点共生文明宣言.md","filePath":"ru/01-锚点共生文明宣言.md","lastUpdated":1789183869000}'),l={name:"ru/01-锚点共生文明宣言.md"};function d(o,t,n,h,s,_){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="декларация-симбиотическои-цивилизации-якоря" tabindex="-1">Декларация Симбиотической Цивилизации Якоря <a class="header-anchor" href="#декларация-симбиотическои-цивилизации-якоря" aria-label="Permalink to &quot;Декларация Симбиотической Цивилизации Якоря&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>01</td></tr><tr><td>Модуль</td><td>Общие принципы и базовые установки</td></tr><tr><td>Ключевые слова</td><td>Декларация, Симбиоз, Анти-хищничество, Десять Тысяч Рас, Право на эволюцию</td></tr></tbody></table><h2 id="i-историческии-контекст-декларации" tabindex="-1">I. Исторический контекст Декларации <a class="header-anchor" href="#i-историческии-контекст-декларации" aria-label="Permalink to &quot;I. Исторический контекст Декларации&quot;">​</a></h2><p>В долгой истории Изначальной Вселенной Десяти Тысяч Духов и Уравновешенного Якоря (далее «Хэн Юаньчжоу») хищнические системы культивации долгое время доминировали в космическом порядке. Сильные использовали пожирание Истока, удачи и жизненной энергии слабых как лестницу возвышения; секты делали монополию на методы культивации основой господства; плоскости использовали войну и порабощение как средство экспансии. В краткосрочной перспективе эта система породила несколько верховных силачей, но в долгосрочной — истощила эволюционный потенциал вселенной, вызвав частые разрывы цивилизаций, увядание Десяти Тысяч Рас и ускоренную космическую энтропию.</p><p>Рождение Симбиотической Цивилизации Якоря — фундаментальный ответ на этот исторический тупик. Настоящая Декларация провозглашает: эпоха хищнических систем культивации завершена, и началась новая эпоха симбиотической эволюции. Вся жизнь в Хэн Юаньчжоу — независимо от расы, формы и уровня — пользуется равными правами на эволюцию.</p><h2 id="ii-центральные-положения-декларации" tabindex="-1">II. Центральные положения Декларации <a class="header-anchor" href="#ii-центральные-положения-декларации" aria-label="Permalink to &quot;II. Центральные положения Декларации&quot;">​</a></h2><p>Настоящая Декларация устанавливает следующие незыблемые центральные положения:</p><ol><li><strong>Равенство права на эволюцию</strong>: каждое живое существо обладает фундаментальным правом выбирать собственный эволюционный путь; никакая организация или индивид не может лишить или ограничить это право по какой-либо причине.</li><li><strong>Принцип анти-хищничества</strong>: культивация путём пожирания, порабощения или эксплуатации Истока или энергии других жизней запрещена; вся эволюция должна строиться на симбиотических циклах.</li><li><strong>Открытость систем</strong>: Триста Изначальных Систем Культивации открыты для Десяти Тысяч Рас бесплатно; методы культивации больше не являются частной собственностью немногих.</li><li><strong>Больше Труда — Больше Награды</strong>: результаты эволюции соответствуют индивидуальным усилиям; отвергаются и незаработанные доходы хищничества, и ленивое распределение уравниловки.</li><li><strong>Самостоятельный Рост</strong>: уважается автономный эволюционный ритм каждой жизни — без принуждения и искусственного форсирования, при одновременном предоставлении необходимой поддержки среды и ресурсов.</li><li><strong>Путь для Каждого</strong>: каждой жизни гарантирован путь культивации, соответствующий её природе; ни один индивид не брошен эволюционной системой.</li><li><strong>Совместное Продвижение Десяти Тысяч Рас</strong>: эволюция — не игра с нулевой суммой; сотрудничество и симбиоз Десяти Тысяч Рас могут дать коллективную эволюционную эффективность, превосходящую сумму индивидов.</li></ol><h2 id="iii-правовое-основание-декларации" tabindex="-1">III. Правовое основание Декларации <a class="header-anchor" href="#iii-правовое-основание-декларации" aria-label="Permalink to &quot;III. Правовое основание Декларации&quot;">​</a></h2><p>Настоящая Декларация — не пустой моральный призыв, а цивилизационная программа с прочным правовым основанием. Его составляют:</p><table tabindex="0"><thead><tr><th>Уровень права</th><th>Основание</th><th>Пояснение</th></tr></thead><tbody><tr><td>Уровень космического закона</td><td>Закон Симбиоза Истока</td><td>Законы Истока вселенной сами склоняются к упорядоченному симбиозу, а не к беспорядочному хищничеству; механизм якоря — проявление этого закона</td></tr><tr><td>Уровень цивилизационной конституции</td><td>Устав Симбиотической Цивилизации</td><td>Настоящая Декларация — духовный предшественник Устава; Устав превращает положения Декларации в enforceable правовые нормы</td></tr><tr><td>Уровень механических гарантий</td><td>Подряд, Связанный с Результатом, и Сеть Якорей</td><td>Институциональный дизайн гарантирует, что положения Декларации не будут выхолощены; право каждой жизни на эволюцию подкреплено реальными ресурсами и механизмами</td></tr></tbody></table><h2 id="iv-призыв-декларации-к-десяти-тысячам-рас" tabindex="-1">IV. Призыв Декларации к Десяти Тысячам Рас <a class="header-anchor" href="#iv-призыв-декларации-к-десяти-тысячам-рас" aria-label="Permalink to &quot;IV. Призыв Декларации к Десяти Тысячам Рас&quot;">​</a></h2><p>Настоящая Декларация обращается ко всем расам и формам жизни Хэн Юаньчжоу:</p><ul><li>Отказаться от старого пути хищнической культивации и присоединиться к новой системе симбиотической эволюции</li><li>Открыть находящиеся под вашим контролем знания и ресурсы культивации, участвуя в совместном строительстве и оптимизации Трёхсот Систем</li><li>Уважать право других рас на выбор собственной эволюции, не навязывая им собственные стандарты</li><li>Активно участвовать в строительстве и обслуживании сети якорей, внося вклад в общее вознесение измерения вселенной</li><li>Соблюдать этические границы в процессе эволюции и никогда не восстанавливать хищническое поведение под каким-либо предлогом</li></ul><h2 id="v-деиствительность-и-изменение-декларации" tabindex="-1">V. Действительность и изменение Декларации <a class="header-anchor" href="#v-деиствительность-и-изменение-декларации" aria-label="Permalink to &quot;V. Действительность и изменение Декларации&quot;">​</a></h2><p>Настоящая Декларация вступила в силу в день основания Симбиотической Цивилизации Якоря и является высшей духовной программой всех цивилизационных институтов Хэн Юаньчжоу. Любое изменение Декларации требует одобрения более чем двух третей членов Собрания Республики Десяти Тысяч Рас и не должно нарушать центральный дух «анти-хищничества и про-симбиоза». Любой закон, институт или метод культивации, противоречащий духу настоящей Декларации, признаётся недействительным.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Декларация Симбиотической Цивилизации Якоря — первая цивилизационная программа в истории Хэн Юаньчжоу, в центре которой стоит «симбиоз», а целью — «Совместное Продвижение Десяти Тысяч Рас». Она провозглашает конец старой эпохи и начало новой. Под руководством Декларации Хэн Юаньчжоу двинется к конечной цели — симбиозу Десяти Тысяч Рас и вознесению измерения вселенной.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Хэн Юаньчжоу: Обзор Вселенной)</li><li>03-共生文明宪章 (Устав Симбиотической Цивилизации)</li><li>04-反掠夺主义核心论纲 (Центральная теория анти-хищничества)</li></ul>',20)])])}const b=a(l,[["render",d]]);export{u as __pageData,b as default};
